    AMMO_PACK:   { icon: '🔧', label: 'Ammo Pack',   max: 3, key: 'AMMO_PACK' },
    FLASHBANG:   { icon: '💥', label: 'Flashbang',   max: 2, key: 'FLASHBANG' },
