      var geo = new THREE.BoxGeometry(w, h, d);
      var shade = Math.floor(0x55 + Math.random() * 0x44);
      var col = (shade << 16) | (shade << 8) | shade;
      var mat = new THREE.MeshLambertMaterial({ color: col });
      var mesh = new THREE.Mesh(geo, mat);
