  var COLOR_PLAYER   = 0x2266ff;
  var COLOR_ENEMY    = 0xff2222;
  var COLOR_CAPTURE  = 0x44ffaa;

  // States
  var STATE_NEUTRAL  = 'NEUTRAL';
  var STATE_PLAYER   = 'PLAYER';
