      'text-shadow:0 0 14px ' + (color || '#ffd700') + ',0 2px 4px #000',
      'pointer-events:none',
      'z-index:515',
      'letter-spacing:3px',
      'white-space:nowrap',
      'opacity:1',
      'transition:opacity 0.4s'
