  var _GEN_MAX_HP = 80;
  var _OVERCHARGE_HP = 400;
  var _OVERCHARGE_DURATION = 8;
  var _RECHARGE_DELAY = 15;
  var _RECHARGE_RATE = 5; // HP per second

