    _iedDefused         = false;
    _iedDetonated       = false;
    _iedPos             = null;
    _ambushActive       = false;
    _ambushTriggered    = [false, false, false];
    _contactTimer       = 0;
    _vehiclesIntact     = [true, true, true, true];
