  var EVT_RADIO_INTERCEPT      = 'RADIO_INTERCEPT';
  var EVT_AMMO_SHORTAGE        = 'AMMO_SHORTAGE';
  var EVT_AIRSTRIKE_SUPPORT    = 'AIRSTRIKE_SUPPORT';
  var EVT_REINFORCEMENT_WAVE   = 'REINFORCEMENT_WAVE';
