    if (_broadcastActive) {
      _broadcastTimer -= dt;
      if (_broadcastTimer <= 0) {
        _broadcastActive = false;
        _showToast('BROADCAST COMPLETE', '#FFFF44');
      }
    }

    // Check morale cascade
    if (Math.random() < dt * 0.5) {
      _checkMoraleCascade();
    }

