    var holoGeo = new T.TorusGeometry(1.2, 0.05, 6, 32);
    var holoMat = new T.MeshBasicMaterial({ color: 0x00ff88, transparent: true, opacity: 0.7 });
    var holoMesh = new T.Mesh(holoGeo, holoMat);
    holoMesh.position.set(0, 10, 0);
