    var bladeGeo  = new THREE.BoxGeometry(0.035, 0.015, 0.32);
    var bladeMat  = new THREE.MeshLambertMaterial({ color: 0xd4d4d4 });
    _bladeMesh    = new THREE.Mesh(bladeGeo, bladeMat);
