        'position:fixed',
        'top:36%',
        'left:50%',
        'transform:translateX(-50%)',
        'color:#ff4400',
        'font-family:monospace',
        'font-size:26px',
        'font-weight:bold',
        'letter-spacing:.15em',
        'text-shadow:0 0 12px #ff4400,0 0 24px #aa2200',
