    _roeLevel          = ROE_PERMISSIVE;
    _civilianKills     = 0;
    _emergencyTimer    = 0;
    _detainCount       = 0;
    _nonlethalCount    = 0;
    _crowdControlScore = 0;
    _selectedNLW       = 0;
    _stunnedEnemies    = [];
    _attackerThreats   = [];
    _playerBlindTimer  = 0;
    _nKeyWas           = false;
    _hKeyWas           = false;
    _fKeyWas           = false;
    _lmbWas            = false;

