  var _reserveDeployed = false; // reserve chute open
  var _chuteHP         = CHUTE_MAX_HP;
  var _chuteInflating  = false;
  var _inflateTimer    = 0;
  var _landed          = false;
  var _velocityY       = 0;    // current downward speed (positive = falling)

  var _dropZoneX       = 0;
  var _dropZoneZ       = 0;

  // Three.js objects
  var _mainChuteGroup   = null;
  var _reserveGroup     = null;
