      dz = p.position.z - pz;
      dist  = Math.sqrt(dx * dx + dz * dz);
      angle = Math.atan2(dz, dx);

      p.position.x += (-Math.sin(angle) * swirlSpeed + windVecX) * dt;
      p.position.z += ( Math.cos(angle) * swirlSpeed + windVecZ) * dt;
      p.position.y += Math.sin(now + i) * 0.5 * dt;

