  var COLOR_OFFICER_SKIN       = 0x8b7355;
  var COLOR_ZONE               = 0x888888;
  var COLOR_ZONE_MARK          = 0x555555;
  var COLOR_ROPE               = 0x8b6914;  // brown hand ties
  var COLOR_GUN                = 0x111111;
  var COLOR_AMBUSH             = 0x3d0000;

  // Negotiation phases
  var PHASE_IDLE               = 'IDLE';
