    epaulettes.position.y = 1.08;
    group.add(epaulettes);

    // Head
    var headGeo  = new THREE.BoxGeometry(0.42, 0.42, 0.42);
    var headMat  = new THREE.MeshLambertMaterial({ color: COLOR_OFFICER_SKIN });
