    var needleAngle = yaw;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(needleAngle);
    ctx.beginPath();
    ctx.moveTo(0, -(r - 14));
    ctx.lineTo(3, 0);
    ctx.lineTo(-3, 0);
    ctx.closePath();
    ctx.fillStyle = '#FF3333';
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(0, r - 14);
    ctx.lineTo(3, 0);
    ctx.lineTo(-3, 0);
