    _casJetStart = new THREE.Vector3(
      pos.x + Math.cos(angle) * dist,
      CAS_JET_Y,
      pos.z + Math.sin(angle) * dist
    );
    _casJetEnd = new THREE.Vector3(
      pos.x - Math.cos(angle) * dist,
      CAS_JET_Y,
      pos.z - Math.sin(angle) * dist
    );
