    _phase  = 0;
    _phaseTimer = 0;
    _siegeActive = false;
    _strongpoints = [];
    _perimeterPosts = [];
    _perimeterLines = null;
    _tracers = [];
    _alarmActive = false;
    _alarmTimer = 0;
    _enemyMorale = 100;
    _surrendered = false;
    _suppressTimer = 0;
    _supplyTimer = 0;
    _commandPost = null;
    _batteringRam = null;
    _ladder = null;
    _siegeTower = null;
    _supplyWagon = null;
