    var supGeo  = new THREE.CylinderGeometry(0.022, 0.022, 0.18, 8);
    var supMat  = new THREE.MeshLambertMaterial({ color: 0x1a1a1a });
    _suppressorMesh = new THREE.Mesh(supGeo, supMat);
