    /* main rotor — CylinderGeometry radius 4 */
    var mainRotorGeo = new THREE.CylinderGeometry(4, 4, 0.12, 12, 1, false);
    var mainRotorMat = new THREE.MeshLambertMaterial({ color: 0x1a1a1a, side: THREE.DoubleSide });
