    if (anyDead) {
      endMission(false);
      return;
    }

    // ── Mission success: all hostages extracted ────────────────
    var numExtracted = 0;
    var numAlive = 0;
    for (var si = 0; si < hostages.length; si++) {
      if (hostages[si].extracted && hostages[si].hp > 0) numExtracted++;
      if (hostages[si].hp > 0) numAlive++;
    }

    if (numAlive > 0 && numExtracted >= numAlive) {
      endMission(true);
      return;
    }

