      if (bpm.x < -10 || bpm.x > CANVAS_SIZE + 10 || bpm.y < -10 || bpm.y > CANVAS_SIZE + 10) { continue; }
      _drawSquare(ctx, bpm.x, bpm.y, 5, '#22CC44');
