      'bottom:8px',
      'left:50%',
      'transform:translateX(-50%)',
      'background:rgba(0,20,0,0.85)',
      'color:#88FF88',
      'font:bold 12px monospace',
      'padding:4px 12px',
      'border:1px solid #3A6A3A',
