  var _keysDown         = {};
  var _wsPressedTime    = 0;
  var _wsComboActive    = false;

  /* ── Original scene fog ────────────────────────────────────────────────── */
  var _origFogNear      = 80;
  var _origFogFar       = 350;
  var _origFogColor     = 0xc8d0e0;
  var _origBgColor      = 0xc8d0e0;
