    phase: 'idle',          // idle | freefall | gliding | landed
    nightJump: false,
    staticLine: false,
    altitude: 0,
    verticalSpeed: 0,
    horizontalVel: { x: 0, z: 0 },
    freefallTimer: 0,
    chuteDeployed: false,
    hp: 100,
    score: 0,
    landingScore: 0,
    shakeDuration: 0,
    shakeTime: 0,
