  var WIRE_COLORS = [
    { label: 'RED',    css: '#ff3333', hex: 0xff3333 },
    { label: 'BLUE',   css: '#3355ff', hex: 0x3355ff },
    { label: 'GREEN',  css: '#33cc55', hex: 0x33cc55 },
    { label: 'YELLOW', css: '#ffdd00', hex: 0xffdd00 }
  ];

  // ── State ────────────────────────────────────────────────────────────────────
  var _scene    = null;
  var _camera   = null;

  // Robot state
