  var _networkBlown = false;

  /* CI sweep */
  var _ciTimer      = CI_SWEEP_INTERVAL;
  var _ciActive     = false;
  var _ciRemain     = 0;
  var _ciTargetIdx  = -1;  // which asset is targeted

  /* Key tracking */
  var _keyI         = false;
  var _keyN         = false;
  var _keyD         = false;
  var _keyE         = false;
  var _keyDPrev     = false;
  var _keyEPrev     = false;

  /* Timing */
  var _intelAgeClock = 0;

  /* Enemy-position reveal markers */
  var _revealMarkers = [];  // { mesh, timer, enemy }

  /* Panel DOM */
  var _panel        = null;
  var _hudEl        = null;
  var _canvas       = null;
