    var head = new THREE.Mesh(headGeo, headMat);
    head.position.y = 1.25;
    group.add(head);
    var lapGeo = new THREE.BoxGeometry(0.4, 0.04, 0.3);
    var lapMat = new THREE.MeshLambertMaterial({ color: 0x222233 });
