    var mat = new THREE.MeshLambertMaterial({ color: 0x886644 });
    var mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(sternPos);
    scene.add(mesh);

    depthCharges.push({ mesh: mesh, active: true, timer: 0 });
