      if (boatRecoil > 0) {
        var back2 = new THREE.Vector3(Math.cos(boatHeading + Math.PI), 0, Math.sin(boatHeading + Math.PI));
        playerBoat.mesh.position.add(back2.multiplyScalar(boatRecoil * dt * 10));
        boatRecoil -= dt * 5;
        if (boatRecoil < 0) boatRecoil = 0;
      }

