          enemyBoat.hp -= 80;
          if (enemyBoat.hp <= 0) {
            spawnExplosion(enemyBoat.mesh.position.clone(), 8, 1.0);
            scene.remove(enemyBoat.mesh);
            enemyBoat.active = false;
          }
          sh.active = false; continue;
