    lights.push({
      isSearchlight: true,
      object: searchlight2
    });
    lights.push({
      isSearchlight: true,
      object: searchlight3
    });

    // Floodlights on poles
    var flood1 = createFloodlight(18, 0, 0);
    var flood2 = createFloodlight(-18, 0, 0);
    var flood3 = createFloodlight(0, 0, 18);

    lights.push({
      isFloodlight: true,
      object: flood1
    });
    lights.push({
      isFloodlight: true,
      object: flood2
    });
    lights.push({
      isFloodlight: true,
      object: flood3
    });

