      var bd = buildings[i];
      var dist = Math.sqrt(
        Math.pow(camPos.x - bd.cx, 2) +
        Math.pow(camPos.z - bd.cz, 2)
      );
      if (dist < ENTRY_DIST) {
        if (insideBuilding && currentBuilding === bd) {
          exitBuilding(bd);
        } else {
          enterBuilding(bd);
        }
        return;
      }
