    // Fuselage: 8×1.5×2 at 45° angle
    var fuseGeo = new THREE.BoxGeometry(8, 1.5, 2);
    var fuseMat = makeMat(COLOR_AIRCRAFT);
    var fuselage = makeMesh(fuseGeo, fuseMat);
    fuselage.position.set(0, 0.75, 0);
