    // Fleeing hostages
    _updateFleeingHostages(dt);

    // Threat flashes
    _updateThreatFlash(dt);

    // Gas
    _updateGas(dt);

    // Sniper
    _updateSniper(dt);

    // Exit ring
    _updateExitRing(dt);

