      _drones.push({
        mesh:         mesh,
        hp:           DRONE_HP,
        alive:        true,
        manual:       false,
        loiterActive: false,
        loiterAngle:  0,
        loiterTarget: null,
        dying:        false,
        ecmAffected:  false,
        signalStrength: 100,
        autoReturn:   false
      });
