    ARMOR_REGEN_RATE: 5,
    ARMOR_REGEN_DELAY: 3,
    BOOST_HEIGHT: 8,
    BOOST_DURATION: 0.3,
    BOOST_LIGHT_COLOR: 0xFF6600,
    DOUBLE_JUMP_HEIGHT: 4,
    SHOCKWAVE_MAX_R: 5,
    SHOCKWAVE_SPEED: 8,
    SHOCKWAVE_KILL_R: 5,
    FIST_DURATION: 0.2,
    FIST_RANGE: 4,
    FIST_FLY_Y: 5,
    GATLING_RPS: 20,
    GATLING_BULLET_SPEED: 60,
    GATLING_OVERHEAT_TIME: 4,
    GATLING_BULLET_R: 0.1,
    MISSILE_SPEED: 18,
    MISSILE_TURN_RATE: 3,
    MISSILE_COUNT: 3,
    FUEL_MAX: 100,
    FUEL_JETPACK_DRAIN: 40,
    FUEL_GATLING_DRAIN: 15,
    FUEL_CELL_RESTORE: 35,
    MOMENTUM_LERP: 4,
    MAX_SPEED: 7,
    SUBSYSTEM_DAMAGE_THRESHOLD: 150,
