      var fp = fuelPos[f];
      var fcGeo = new THREE.BoxGeometry(0.7, 0.7, 0.7);
      var fcMat = new THREE.MeshLambertMaterial({ color: 0x00FFAA, emissive: 0x00AA66 });
      var fcMesh = new THREE.Mesh(fcGeo, fcMat);
