      var pGeo = new THREE.CylinderGeometry(0.3, 0.5, ph, 6);
      var pMat = new THREE.MeshLambertMaterial({ color: 0x004488, emissive: 0x001122 });
      var pMesh = new THREE.Mesh(pGeo, pMat);
      pMesh.position.set(rand(-90, 90), ph / 2, rand(-90, 90));
      addOwned(pMesh);
