    _heloGroup.position.z += (targetZ - _heloGroup.position.z) * dt * 1.5;
    _heloGroup.position.x += (0 - _heloGroup.position.x) * dt * 1.5;
    _heloGroup.position.y = _heloAltitude + Math.sin(_clock * 1.5) * 0.3;

