    _currentWave      = 0;
    _waveTimer        = WAVE_INTERVAL;
    _waveActive       = false;
    _jamming          = false;
    _enemyControlTime = 0;
    _signalStrength   = 100;
    _signalBroadcast  = false;
    _broadcastTimer   = 0;
    _airstrikeActive  = false;
    _airstrikeCount   = 0;
    _airstrikeTimer   = 0;
    _climbing         = false;
    _climbHeight      = 0;
    _atTop            = false;
    _sniperActive     = false;
    _repairing        = false;
    _repairTimer      = 0;
    _repairLegIdx     = -1;
    _commanderEnemy   = null;
    _commanderReinfTimer = 0;
    _fortBuilding     = false;
    _fortType         = null;
