  var FLIGHT_MIN         = 3.0;      // seconds
  var FLIGHT_MAX         = 5.0;
  var EXPLOSION_RANGE    = 12;       // base damage radius
  var EXPLOSION_LIGHT_R  = 20;
  var DAMAGE_RADIUS_HE   = 15;
  var SMOKE_RADIUS       = 10;
  var SMOKE_LIFE         = 20;
  var ILLUM_DESCENT      = 2.0;      // units/sec downward
  var ILLUM_LIFE         = 30;
  var WP_COUNT           = 5;
  var WP_BURN_LIFE       = 3.0;
  var AMMO_HE_START      = 8;
  var AMMO_SMOKE_START   = 6;
