  var _active        = false;
  var _score         = 0;
  var _hvtStatus     = 'LOCATED';   // 'LOCATED' | 'CAPTURED' | 'ELIMINATED'
  var _exfilMode     = 'NONE';      // 'NONE' | 'HELO' | 'VEHICLE'
  var _missionClear  = false;
  var _missionFailed = false;

  /* ── Input ──────────────────────────────────────────────────────────────── */
