  var _heloCalled      = false;
  var _heloArrivalTimer= 0;
  var _heloHoverTimer  = 0;
  var _heloAngle       = 0;
  var HELO_ORBIT_RADIUS= 40;
  var HELO_ALTITUDE    = 40;
  var HELO_ARRIVAL_TIME= 30;
