        new THREE.Vector3(cx - hw, cy - hh, cz),
        new THREE.Vector3(cx + hw, cy - hh, cz),
        new THREE.Vector3(cx + hw, cy + hh, cz),
        new THREE.Vector3(cx - hw, cy + hh, cz)
