    _gameOver      = false;
    _missionClear  = false;
    _gameTimer     = 0;
    _flareActive   = false;
    _shuttingDown  = false;
    _shutdownTimer = 0;
    _o2Current     = _o2Station;
    _inStation     = true;
    _bootsOn       = false;
    _breaches      = [];

