    if (_keys['ArrowLeft'])  _playerX -= spd * dt;
    if (_keys['ArrowRight']) _playerX += spd * dt;
    if (_keys['ArrowUp'])    _playerZ -= spd * dt;
    if (_keys['ArrowDown'])  _playerZ += spd * dt;

