    _ladders = [];
    _defenders = [];

    _scene = null;
    _camera = null;
    _clock = null;
    _castleGroup = null;
    _gateMesh = null;
    _catapult = null;
    _ram = null;
    _trebuchet = null;
    _keepBoss = null;
