  /* ── Prison structures ─────────────────────────────────────────────────── */
  var _prisonGroup     = null;
  var _cellBlock       = null;
  var _cellDoors       = [];
  var _guardTower      = null;
  var _wardenOffice    = null;
  var _cafeteria       = null;
  var _safeRoom        = null;
  var _kitchenPos      = null;

  /* ── Inmates ───────────────────────────────────────────────────────────── */
  var _gangA = [];  // red inmates 0xAA2222, 20 total
  var _gangB = [];  // blue inmates 0x2222AA, 20 total
  var GANG_SIZE = 20;

  /* ── Ringleader ────────────────────────────────────────────────────────── */
  var _ringleader     = null;
