    _phase         = 'ROBBERY';
    _outcome       = '';
    _mouseX        = 0;
    _mouseY        = 0;
    _yaw           = 0;
    _pitch         = 0;
    _mouseDown     = false;
    _keyPressTime  = { T: 0, R: 0 };
    _keys          = {};
    _eKeyWasDown   = false;
    _dKeyWasDown   = false;
    _gKeyWasDown   = false;
    _smokeTimer    = 0;

