    _scene.background = new THREE.Color(0x001122);
    _scene.fog        = new THREE.FogExp2(0x001A33, 0.03);

    /* Ambient light */
    var ambient = new THREE.AmbientLight(0x002244, 0.5);
    ambient.name = '_sw_ambient';
    _scene.add(ambient);

