          /* Near miss */
          ten.hp -= 50;
          spawnExplosion(torp.mesh.position.clone(), 3);
          _scene.remove(torp.mesh);
          _torpedoes.splice(ti, 1);
          torpHit = true;
          if (ten.hp <= 0) { killEnemy(tei); }
          break;
