      pirate.position.set(pd.x, yBase, pd.z);

      // Hat
      var hatGeo = new THREE.BoxGeometry(0.8, 0.35, 0.5);
      var hat = makeMesh(hatGeo, 0x221100);
      hat.position.set(0, 1.05, 0);
