      var epos = e.mesh.position;
      var pdist = dist3(state.playerPos, epos);
      if (pdist < 2) {
        state.playerHP -= 15 * dt;
        if (state.playerHP <= 0) {
          state.playerHP = 0;
          gameOver(false);
        }
      }

