    _periscopeRise    = 0;
    _selectedTube     = 0;
    _enemyKnown       = false;
    _decoyActive      = false;
    _decoyTimer       = 0;
    _icbmLaunched     = false;
    _sonarTimer       = 15;
    _sonarContact     = '';
    _sonarContactTimer = 0;
    _falseContactActive = false;
    _sonarOfficerFacing = false;
    _torpedoes        = [];
    _depthCharges     = [];
    _explosions       = [];
