    var ambient = new THREE.AmbientLight(0xffffff, 0.6);
    _scene.add(ambient);
    var sun = new THREE.DirectionalLight(0xffffff, 0.8);
    sun.position.set(20, 40, 20);
    _scene.add(sun);

    // Zone center (random)
    _zoneCenter = _v3(_rnd(-10, 10), 0, _rnd(-10, 10));
    _zoneCurRadius = 40;
    _zoneStageIdx = 0;
    _gameTime = 0;

    _buildMap();
    _spawnPlayer();
