    _cliffL         = null;
    _cliffR         = null;
    _extractZone    = null;
    _player         = null;
    _radioMesh      = null;
    _helicopter     = null;
    _ambushPositions = [];
    _boulders       = [];
    _vehicles       = [];
    _soldiers       = [];
