    _lastTime = timestamp;

    if (!_active) return;

    _fireCooldown = Math.max(0, _fireCooldown - _dt);

    _updatePlayer(_dt);
    _updateConvoy(_dt);
    _updateBoulders(_dt);
    _updateBullets(_dt);
    _updateAirSupport(_dt);
    _updateCargoTimer(_dt);
    _updateExplosions(_dt);

