    _updatePlayerMovement(dt);
    _updateEnemyAI(dt);
    _updateAlliedMages(dt);
    _updateProjectiles(dt);
    _updateFrostWalls(dt);
    _updateLightningBolts(dt);
    _updateShield(dt);
    _updateBoss(dt);
    _updateHUD();

