    geo  = new THREE.BoxGeometry(10, 4, 10);
    mesh = makeMesh(geo, 0x555555);
    mesh.position.set(sx, 2, sz);
    _scene.add(mesh);
    _envObjects.push(mesh);

    /* Doorway outline */
