    _stunTimer       = 0;
    _missionTimer    = 300;
    _waveTimer       = 60;
    _waveCount       = 0;
    _killSwitchArmed   = true;
    _killSwitchInserted = false;
    _insertTimer       = 0;
    _insertHolding     = false;
    _shieldsDown     = 0;
    _keyR = false;
    _keyB = false;
    _keys = {};
    _yaw  = 0;
    _pitch = 0;
    _shootCooldown = 0;
    _grenades = 0;
    _hasRifle = false;
    _conveyorHazard = true;
    _gasStunTimer = 0;
    _sprinklersOn = false;
    _beamSpawnTimer = 0;
    _craneSwing = 0;
