  function loop() {
    if (!state.active) { return; }
    state.animId = requestAnimationFrame(loop);
    var dt = Math.min(state.clock.getDelta(), 0.1);

    if (!state.gameOver) {
      // Phase timer
      state.phaseTimer -= dt;
      if (state.phaseTimer <= 0) {
        state.phaseTimer = 0;
        triggerTimerDeath();
      }

      updatePlayer(dt);
      updateEnemies(dt);
      updateBullets(dt);
      checkArtifact();
      updatePriest(dt);
      updateElevator(dt);
      updatePortal(dt);
      updateFlash(dt);
      updateHUD();
    }

    state.renderer.render(state.scene, state.camera);
  }

