        'background:rgba(0,0,0,0.8)',
        'color:#FFEECC',
        'font:bold 15px monospace',
        'padding:5px 16px',
        'border-radius:4px',
        'pointer-events:none',
        'z-index:9999',
        'max-width:80vw',
        'text-align:center'
