    state.diamonds = [];
    state.motionSensors = [];
    state.laserLines = null;
    state.vaultDoor = null;
    state.disguiseMesh = null;
    state.keyCardMesh = null;
    state.getawayCar = null;
    state.helicopter = null;
    state.raycaster = null;
    state.dDown = false;
    state.hDown = false;
