          var bus = _buses[bi];
          if (bus.destroyed || bus.hp >= BUS_HP_MAX) continue;
          var bPos = bus.group.position;
          var bdx  = bPos.x - _playerPos.x;
          var bdz  = bPos.z - _playerPos.z;
          var bd   = Math.sqrt(bdx * bdx + bdz * bdz);
          if (bd < nearDist) { nearDist = bd; nearBus = bi; }
