    var bestD = DEBRIS_INTERACT_DIST;
    for (var i = 0; i < _debrisList.length; i++) {
      var d = _debrisList[i];
      if (!d.alive) { continue; }
      var dx = d.mesh.position.x - _playerPos.x;
      var dz = d.mesh.position.z - _playerPos.z;
      var dd = Math.sqrt(dx * dx + dz * dz);
      if (dd < bestD) { bestD = dd; best = i; }
    }
