    document.removeEventListener('keyup',     _onKeyUp);
    document.removeEventListener('mousemove', _onMouseMove);
    document.removeEventListener('mousedown', _onMouseDown);
    document.removeEventListener('mouseup',   _onMouseUp);
    document.removeEventListener('click',     _onMouseClick);

    /* reset state */
    _active      = false;
    _playerPos   = { x: 0, y: 0.1, z: 0 };
    _playerHP    = 100;
    _onDebris    = false;
    _onDebrisIdx = -1;
    _submerged   = false;
    _bleeding    = false;
    _dead        = false;
    _won         = false;
    _hasHarpoon  = false;
    _harpoonShots= 0;
    _harpoonReload = 0;
    _hasFlare    = false;
    _flareFired  = false;
    _flarePos    = null;
    _flareTimer  = 0;
    _knifeTimer  = 0;
    _keys        = {};
    _yaw         = 0;
    _pitch       = 0;
    _sDown       = false;
    _aDown       = false;
    _time        = 0;
