  var SHOOT_DAMAGE        = 25;
  var INTERACT_RANGE      = 2.5;
  var FREE_TIME           = 1.5;      // seconds to free a hostage
  var DISARM_TIME         = 4.0;      // seconds to disarm detonator
  var SPEED_BASE          = 300;      // km/h base train speed
