  var _active             = false;
  var _gameOver           = false;
  var _won                = false;
  var _timer              = MISSION_TIME;
  var _lastTime           = 0;

  /* ── Player ─────────────────────────────────────────────────────────────── */
  var _playerPos          = null;   // THREE.Vector3
  var _playerHP           = PLAYER_HP;
  var _yaw                = 0;
  var _pitch              = 0;
