    holdBarEl.style.cssText = 'width:0%;height:100%;background:#44AAFF;border-radius:4px;';
    holdEl.appendChild(holdBarEl);
    document.body.appendChild(holdEl);
    _hudEl.holdEl    = holdEl;
    _hudEl.holdBarEl = holdBarEl;
