  var _gtPressTime = { G: 0, T: 0 };
  var GT_WINDOW    = 400;

  /* ── Game state ───────────────────────────────────────────────────────── */
  var _active        = false;
  var _victory       = false;
  var _defeat        = false;
  var _msgTimer      = 0;
  var _msgText       = '';

  /* ── Player ───────────────────────────────────────────────────────────── */
  var _playerPos     = { x: 0, y: 1.7, z: 30 };
  var _playerHP      = 100;
  var _playerSpeed   = 6;
  var _yaw           = 0;
  var _pitch         = 0;
  var _keys          = {};
  var _mouseDown     = false;

  /* ── Inventory ────────────────────────────────────────────────────────── */
  var _regularAmmo   = 30;
  var _silverBullets = 0;
  var _silverOre     = 0;
  var _holyWater     = 0;
  var _totemWatered  = [];   // which totems have been holy-watered (index)

